SELECT CONCAT(YEAR(data), ' - ', ELT(MONTH(data),'JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ')) AS periodo, SUM(valor) AS total FROM Serie_Historica WHERE  data BETWEEN '2023-01-01' AND '2026-10-01' AND serie = 'PRODUCAO' AND segmento = 'VEICULOS LEVES' AND categoria = 'AUTOMOVEIS' GROUP BY CONCAT(YEAR(data), ' - ', ELT(MONTH(data),'JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ')) HAVING 1=1;
